# virtual FS -> bundle -> sandboxed run
files = {
    'main.js': 'import {hi} from "./hi.js"; hi();',
    'hi.js': 'export function hi() { log("hi"); }',
}

def bundle(entry):  # esbuild-wasm in production; concatenation here
    seen, out = set(), []
    def visit(f):
        if f in seen:
            return
        seen.add(f)
        for line in files[f].split('\n'):
            if line.startswith('import'):
                dep = line.split('"')[1]
                visit(dep[2:] if dep.startswith('./') else dep)
        out.append('// %s\n' + files[f])
    visit(entry)
    return '\n'.join(out)

print(bundle('main.js')[:80], '...')
print('files -> bundle (esbuild-wasm) -> sandboxed iframe')

# HMR: swap the changed module, keep app state
modules = {'counter': {'code': 'v1', 'state': {'n': 5}}}

def hot_swap(name, new_code):
    state = modules[name]['state']  # state SURVIVES
    modules[name] = {'code': new_code, 'state': state}
    return 'swapped %s: code=%s state=%s (no reload)' % (name, new_code, state)

print(hot_swap('counter', 'v2'))
print('no accept handler -> full reload fallback (state lost, honest)')
